<?php defined('ABSPATH') || exit; $issue = get_post_meta(get_the_ID(), '_mg_issue', true) ?: array(); ?>
<section class="issue-detail"><div class="issue-detail-cover"><?php echo mg_theme_image($issue['cover'] ?? get_the_post_thumbnail_url(null, 'full'), get_the_title() . ' 표지', 'fetchpriority="high"'); ?></div><div><?php echo mg_theme_eyebrow('VOL. ' . ($issue['volume'] ?? '') . ' / ' . ($issue['month'] ?? '')); ?><h1><?php the_title(); ?></h1><div class="mg-native-content"><?php the_content(); ?></div><?php if (!empty($issue['isDemo'])) { ?><p class="demo-note">시연용 호입니다. 실제 발행·판매 정보는 운영자가 확정한 뒤 안내합니다.</p><?php } echo mg_theme_button('구독 안내', 'subscribe/', 'dark'); ?></div></section>
<?php $posts = array(); foreach ($issue['articleIds'] ?? array() as $source_id) { $found = get_posts(array('post_type' => 'post','post_status' => 'publish','meta_key' => '_mg_source_id','meta_value' => $source_id,'numberposts' => 1)); if ($found) $posts[] = $found[0]; } ?>
<section class="section"><div class="section-heading"><h2>이번 호의 <em>이야기</em></h2><span><?php echo count($posts); ?> STORIES</span></div><?php mg_theme_cards($posts); ?></section>
